import math

def process_sequence(b_0, n):
    b_n = b_0
    for i in range(1, n+1):
        b_n = b_n + math.sqrt(b_n - 1)
    return b_n

def compute_final_answer(b_0):
    product = b_0
    for i in range(1, 1000):
        product *= process_sequence(b_0, i)
    return product

